-- public.event_rsvp_summary (counts for every viewer, never names)
begin;
create extension if not exists pgtap with schema extensions;
select * from no_plan();
create function pg_temp.n(q text) returns int language plpgsql as $f$ declare c int; begin execute q; get diagnostics c = row_count; return c; end $f$;

update public.profiles set display_name = 'Pat Ava' where id = 'a2222222-2222-2222-2222-222222222222';
-- Team A (club-linked, soccer): admin, coach, parents Ava/Ben, player Teen. Team B (basketball): coach B, parent Other.
-- Active on A: Ava, Ben, Teen. Inactive on A: Dan. Active on B: Cleo, Ivy (Ava's second team).

reset role;
reset role; set local role anon; select set_config('request.jwt.claims', '{"role":"anon"}', true);
select throws_ok($$ select * from public.event_rsvp_summary('e1000000-0000-0000-0000-000000000001') $$, '42501', null, 'anonymous users cannot call the summary');
reset role; select set_config('request.jwt.claims', '{"sub":"a2222222-2222-2222-2222-222222222222","role":"authenticated"}', true); set local role authenticated;
select is((select going || '/' || not_going || '/' || maybe || '/' || no_reply from public.event_rsvp_summary('e1000000-0000-0000-0000-000000000001')), '1/1/0/1', 'a parent sees aggregate counts (active roster: 3, one with no reply)');
select is((select count(*)::int from information_schema.columns where table_name = 'event_rsvp_summary'), 0, 'the summary exposes no table columns');
select is((select string_agg(a, ',') from (select unnest(proargnames) a from pg_proc where proname = 'event_rsvp_summary') x), 'p_event_id,going,not_going,maybe,no_reply', 'and the result has no name columns');
reset role; select set_config('request.jwt.claims', '{"sub":"a7777777-7777-7777-7777-777777777777","role":"authenticated"}', true); set local role authenticated;
select is((select going from public.event_rsvp_summary('e1000000-0000-0000-0000-000000000001')), 1, 'a player sees counts');
reset role; select set_config('request.jwt.claims', '{"sub":"a5555555-5555-5555-5555-555555555555","role":"authenticated"}', true); set local role authenticated;
select is((select no_reply from public.event_rsvp_summary('e1000000-0000-0000-0000-000000000001')), 1, 'a linked club admin sees counts');
reset role; select set_config('request.jwt.claims', '{"sub":"a1111111-1111-1111-1111-111111111111","role":"authenticated"}', true); set local role authenticated;
select is((select going || '/' || not_going || '/' || maybe || '/' || no_reply from public.event_rsvp_summary('e1000000-0000-0000-0000-000000000001')), '1/1/0/1', 'staff see the same counts');
reset role; select set_config('request.jwt.claims', '{"sub":"a4444444-4444-4444-4444-444444444444","role":"authenticated"}', true); set local role authenticated;
select is_empty($$ select * from public.event_rsvp_summary('e1000000-0000-0000-0000-000000000001') $$, 'a parent on another team gets nothing');
reset role; select set_config('request.jwt.claims', '{"sub":"a9999999-9999-9999-9999-999999999999","role":"authenticated"}', true); set local role authenticated;
select is_empty($$ select * from public.event_rsvp_summary('e1000000-0000-0000-0000-000000000001') $$, 'a stranger gets nothing');
reset role; select set_config('request.jwt.claims', '{"sub":"a6666666-6666-6666-6666-666666666666","role":"authenticated"}', true); set local role authenticated;
select is_empty($$ select * from public.event_rsvp_summary('e1000000-0000-0000-0000-000000000001') $$, 'staff of another team get nothing');
reset role;
update public.team_players set status = 'inactive' where id = 'd4000000-0000-0000-0000-000000000004';
reset role; select set_config('request.jwt.claims', '{"sub":"a2222222-2222-2222-2222-222222222222","role":"authenticated"}', true); set local role authenticated;
select is((select no_reply from public.event_rsvp_summary('e1000000-0000-0000-0000-000000000001')), 0, 'a player who leaves the active roster no longer counts as no-reply');
select * from finish();
rollback;
